49:.radar-head { display: flex; align-items: center; gap: 20px; padding: 12px 32px; border-bottom: 1px solid var(--radar-line); background: var(--radar-head-bg); white-space: nowrap; }
54:.radar-screen:fullscreen .radar-head-logo { display: flex; align-items: center; padding-right: 20px; border-right: 1px solid var(--radar-line); }
60:.radar-brand { display: flex; align-items: center; gap: 12px; line-height: 1.05; }
66:.radar-feed-pill { display: flex; align-items: center; gap: 8px; padding: 6px 12px; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 999px; font-family: var(--radar-mono); font-size: 12px; letter-spacing: 1px; white-space: nowrap; }
67:.radar-feed-pill--stale { border-color: var(--radar-amber); color: var(--radar-stale-ink); }
68:.radar-feed-pill--stale .radar-live-dot { background: var(--radar-amber); box-shadow: 0 0 10px var(--radar-amber); }
70:.radar-clock { display: flex; flex-direction: column; align-items: flex-end; line-height: 1.1; font-family: var(--radar-mono); }
81:.radar-days { display: flex; align-items: center; gap: 6px; font-family: var(--radar-mono); font-size: 13px; letter-spacing: 1px; }
86:.radar-feed-pill--replay { border-color: var(--radar-amber); background: rgba(255, 181, 71, 0.1); color: var(--radar-stale-ink); }
92:.radar-main { flex-grow: 1; display: grid; grid-template-columns: minmax(340px, 470px) minmax(0, 1fr); gap: clamp(28px, 4vw, 72px); padding: 24px 32px 28px; min-height: 0; }
95:/* The feed. */
96:.radar-feed { display: flex; flex-direction: row; gap: 16px; min-width: 0; }
97:.radar-feed-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; }
99:.radar-feed-head h1 { margin: 4px 0 0; font-size: 24px; font-weight: 600; letter-spacing: 1px; }
103:.radar-locked { position: relative; }
105:.radar-filterbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: -6px; padding: 6px 4px 6px 12px; border-radius: 8px; background: rgba(59, 130, 246, 0.06); }
106:.radar-locked-close { position: absolute; top: 12px; right: 12px; }
107:.radar-locked-meta { padding-right: 40px; }
111:.radar-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; border: 1px solid var(--radar-line); border-radius: 10px; overflow: hidden; background: var(--radar-panel-bg); }
112:.radar-kpi { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; padding: 14px 14px 12px; border: 0; border-radius: 0; border-top: 2px solid transparent; border-right: 1px solid var(--radar-line); background: var(--radar-panel-bg); color: inherit; text-align: left; cursor: pointer; }
126:.radar-chips { display: grid; grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); gap: 8px; }
133:.radar-locked { display: flex; flex-direction: row; gap: 10px; padding: 16px 18px; border-radius: 12px; border: 1px solid rgba(255, 181, 71, 0.5); background: linear-gradient(135deg, rgba(255, 181, 71, 0.1), rgba(59, 130, 246, 0.05)); }
134:.radar-locked-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; font-family: var(--radar-mono); font-size: 11px; letter-spacing: 2px; color: var(--radar-dim); }
135:.radar-locked-mark { color: var(--radar-amber-ink); }
136:.radar-locked-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding-right: 36px; }
137:.radar-locked-title { font-size: 21px; font-weight: 600; line-height: 1.2; }
138:.radar-locked-kind { font-size: 14px; font-weight: 400; line-height: 1.4; color: var(--radar-muted); }
139:.radar-locked-facts { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 18px; }
140:.radar-locked-fact-label { display: block; margin-bottom: 2px; font-family: var(--radar-mono); font-size: 10px; letter-spacing: 0.8px; color: var(--radar-dim); }
141:.radar-locked-fact-value { font-size: 15px; }
142:.radar-locked-detail { font-size: 14px; line-height: 1.4; color: var(--radar-muted); }
143:.radar-locked-actions { display: flex; align-items: center; gap: 8px; }
157:.radar-list { display: flex; flex-direction: column; max-height: 540px; overflow-y: auto; padding-right: 4px; border-top: 1px solid var(--radar-line); }
160:.radar-row { display: grid; grid-template-columns: 56px auto minmax(0, 1fr) auto; gap: 12px; align-items: center; width: 100%; min-height: 54px; padding: 9px 10px 9px 12px; border: 0; border-bottom: 1px solid rgba(59, 130, 246, 0.08); border-left: 2px solid transparent; border-radius: 0; background: transparent; color: inherit; text-align: left; cursor: pointer; }
165:.radar-doc-detail { display: grid; gap: 10px; margin: 0; }
166:.radar-doc-detail-row { display: grid; grid-template-columns: 130px minmax(0, 1fr); gap: 12px; align-items: baseline; }
171:.radar-row-when { display: flex; flex-direction: column; gap: 2px; font-family: var(--radar-mono); }
174:.radar-row-text { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
190:.radar-panel { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
196:.radar-toolbar { --radar-heading-h: 38px; display: flex; align-items: center; gap: 14px; font-family: var(--radar-mono); font-size: 12px; letter-spacing: 1.5px; color: var(--radar-dim); }
197:.radar-toolbar-info { flex: 1 1 auto; min-width: 0; display: flex; flex-wrap: wrap; align-content: flex-start; align-items: center; column-gap: 14px; row-gap: 14px; height: var(--radar-heading-h); overflow: hidden; white-space: nowrap; }
203:.radar-toolbar-sweep { display: flex; align-items: center; gap: 6px; }
237:.radar-blip { position: absolute; width: 30px; height: 30px; margin: -15px 0 0 -15px; padding: 0; border: 0; background: transparent; display: flex; align-items: center; justify-content: center; cursor: pointer; }
255:.radar-telemetry { display: flex; flex-direction: column; gap: 8px; padding: 12px 16px 10px; border-radius: 10px; border: 1px solid rgba(59, 130, 246, 0.14); background: var(--radar-telemetry-bg); }
257:.radar-arrivals { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
263:.radar-arrivals-axis { display: flex; justify-content: flex-end; font-family: var(--radar-mono); font-size: 10px; letter-spacing: 1.5px; color: var(--radar-faint); }
